add_action( 'rest_api_init', function () {
    $schema = static function () {
        return array(
            '$schema'    => 'http://json-schema.org/draft-04/schema#',
            'title'      => 'wpbp_venue',
            'type'       => 'object',
            'properties' => array(
                'name'        => array( 'type' => 'string', 'context' => array( 'view', 'edit' ) ),
                'capacity'    => array( 'type' => 'integer', 'context' => array( 'view', 'edit' ) ),
                'owner_email' => array( 'type' => 'string', 'context' => array( 'edit' ) ),
            ),
        );
    };
    register_rest_route(
        'wpbp/v1',
        '/venues',
        array(
            array(
                'methods'             => WP_REST_Server::READABLE,
                'args'                => array(
                    'context' => array( 'type' => 'string', 'enum' => array( 'view', 'edit' ), 'default' => 'view' ),
                ),
                'permission_callback' => static function ( WP_REST_Request $request ) {
                    if ( 'edit' === $request['context'] && ! current_user_can( 'edit_posts' ) ) {
                        return new WP_Error( 'rest_forbidden_context', 'Sorry, you are not allowed to edit venues.', array( 'status' => rest_authorization_required_code() ) );
                    }
                    return true;
                },
                'callback'            => static function ( WP_REST_Request $request ) use ( $schema ) {
                    $item_schema = $schema();
                    $context     = (string) $request['context'];
                    $items       = array();
                    foreach ( (array) get_option( 'wpbp_venues', array() ) as $venue ) {
                        $items[] = rest_filter_response_by_context( $venue, $item_schema, $context );
                    }
                    return rest_ensure_response( $items );
                },
            ),
            'schema' => $schema,
        )
    );
} );

