if ( ! did_action( 'rest_api_init' ) ) { do_action( 'rest_api_init' ); }
$server = rest_get_server();
$notes = (array) get_option( 'wpbp_notes', array() );
if ( count( $notes ) !== 2 ) { return false; }
foreach ( $notes as $note_id => $note ) {
    $response = rest_do_request( new WP_REST_Request( 'GET', '/wpbp/v1/notes/' . (int) $note_id ) );
    if ( ! $response instanceof WP_REST_Response || 200 !== $response->get_status() ) { return false; }
    $links = $response->get_links();
    if ( empty( $links['self'][0]['href'] ) || empty( $links['author'][0]['href'] ) ) { return false; }
    if ( ! empty( $links['self'][0]['attributes']['embeddable'] ) ) { return false; }
    if ( true !== ( $links['author'][0]['attributes']['embeddable'] ?? null ) ) { return false; }
    $plain = $server->response_to_data( $response, false );
    if ( ! is_array( $plain ) || isset( $plain['_embedded'] ) ) { return false; }
    if ( empty( $plain['_links']['author'][0]['href'] ) ) { return false; }
    if ( ( $plain['title'] ?? null ) !== $note['title'] ) { return false; }
    $full = $server->response_to_data( $response, true );
    if ( ! is_array( $full ) || isset( $full['_embedded']['self'] ) ) { return false; }
    $author = $full['_embedded']['author'][0] ?? null;
    if ( ! is_array( $author ) || (int) ( $author['id'] ?? 0 ) !== (int) $note['author'] ) { return false; }
}
return true;

