add_action( 'rest_api_init', function () {
    register_rest_route(
        'wpbp/v1',
        '/notes/(?P<id>[\\d]+)',
        array(
            'methods'             => WP_REST_Server::READABLE,
            'permission_callback' => '__return_true',
            'args'                => array( 'id' => array( 'type' => 'integer' ) ),
            'callback'            => static function ( WP_REST_Request $request ) {
                $notes   = (array) get_option( 'wpbp_notes', array() );
                $note_id = (int) $request['id'];
                if ( ! isset( $notes[ $note_id ] ) ) {
                    return new WP_Error( 'wpbp_note_not_found', 'Note not found.', array( 'status' => 404 ) );
                }
                $note     = $notes[ $note_id ];
                $response = rest_ensure_response(
                    array(
                        'id'     => $note_id,
                        'title'  => $note['title'],
                        'author' => (int) $note['author'],
                    )
                );
                $response->add_link( 'self', rest_url( 'wpbp/v1/notes/' . $note_id ) );
                $response->add_link( 'author', rest_url( 'wp/v2/users/' . (int) $note['author'] ), array( 'embeddable' => true ) );
                return $response;
            },
        )
    );
} );

