add_action( 'rest_api_init', function () {
    register_rest_route(
        'wpbp/v1',
        '/bookings',
        array(
            'methods'             => WP_REST_Server::CREATABLE,
            'permission_callback' => '__return_true',
            'args'                => array(
                'room'   => array(
                    'type'     => 'string',
                    'enum'     => array( 'harbor', 'cedar' ),
                    'required' => true,
                ),
                'guests' => array(
                    'type'    => 'integer',
                    'minimum' => 1,
                    'default' => 2,
                ),
            ),
            'callback'            => static function ( WP_REST_Request $request ) {
                $room   = (string) $request['room'];
                $guests = (int) $request['guests'];
                $booked = (array) get_option( 'wpbp_bookings', array() );
                $error  = new WP_Error();
                if ( in_array( $room, $booked, true ) ) {
                    $error->add( 'wpbp_room_taken', 'That room is already booked.', array( 'status' => 409 ) );
                }
                if ( $guests > 4 ) {
                    $error->add( 'wpbp_over_capacity', 'That room does not hold that many guests.', array( 'status' => 400 ) );
                }
                if ( $error->has_errors() ) {
                    return $error;
                }
                $booked[] = $room;
                update_option( 'wpbp_bookings', $booked );
                $response = rest_ensure_response( array( 'room' => $room, 'guests' => $guests ) );
                $response->set_status( 201 );
                return $response;
            },
        )
    );
} );

