add_action( 'rest_api_init', function () {
    $schema = array(
        '$schema'    => 'http://json-schema.org/draft-04/schema#',
        'title'      => 'wpbp_widget',
        'type'       => 'object',
        'properties' => array(
            'id'     => array( 'type' => 'integer', 'readonly' => true, 'context' => array( 'view', 'edit' ) ),
            'name'   => array( 'type' => 'string', 'required' => true, 'minLength' => 2, 'context' => array( 'view', 'edit' ) ),
            'colour' => array( 'type' => 'string', 'enum' => array( 'blue', 'red', 'green' ), 'default' => 'blue', 'context' => array( 'view', 'edit' ) ),
        ),
    );
    register_rest_route(
        'wpbp/v1',
        '/widgets',
        array(
            array(
                'methods'             => WP_REST_Server::CREATABLE,
                'permission_callback' => '__return_true',
                'args'                => rest_get_endpoint_args_for_schema( $schema, WP_REST_Server::CREATABLE ),
                'callback'            => static function ( WP_REST_Request $request ) {
                    $widgets      = (array) get_option( 'wpbp_widgets', array() );
                    $widget_id    = $widgets ? max( array_map( 'intval', array_keys( $widgets ) ) ) + 1 : 1;
                    $widgets[ $widget_id ] = array( 'name' => (string) $request['name'], 'colour' => (string) $request['colour'] );
                    update_option( 'wpbp_widgets', $widgets );
                    $response = rest_ensure_response( array_merge( array( 'id' => $widget_id ), $widgets[ $widget_id ] ) );
                    $response->set_status( 201 );
                    return $response;
                },
            ),
            'schema' => static function () use ( $schema ) { return $schema; },
        )
    );
    register_rest_route(
        'wpbp/v1',
        '/widgets/(?P<id>[\\d]+)',
        array(
            array(
                'methods'             => WP_REST_Server::EDITABLE,
                'permission_callback' => '__return_true',
                'args'                => rest_get_endpoint_args_for_schema( $schema, WP_REST_Server::EDITABLE ),
                'callback'            => static function ( WP_REST_Request $request ) {
                    $widgets   = (array) get_option( 'wpbp_widgets', array() );
                    $widget_id = (int) $request['id'];
                    if ( ! isset( $widgets[ $widget_id ] ) ) {
                        return new WP_Error( 'wpbp_widget_not_found', 'Widget not found.', array( 'status' => 404 ) );
                    }
                    foreach ( array( 'name', 'colour' ) as $field ) {
                        if ( null !== $request[ $field ] ) {
                            $widgets[ $widget_id ][ $field ] = (string) $request[ $field ];
                        }
                    }
                    update_option( 'wpbp_widgets', $widgets );
                    return rest_ensure_response( array_merge( array( 'id' => $widget_id ), $widgets[ $widget_id ] ) );
                },
            ),
            'schema' => static function () use ( $schema ) { return $schema; },
        )
    );
} );

